%calculate fidelity in terms of color differences
for i=1:size(spd,2)-1
    spdi=[spd(:,1),spd(:,i+1)];
    [nDEi_,nDEavg_,sampleset,Jabt_,Jabr_,T_,dc_,xyzt_,xyzr_]=cri_engine_(spdi, sampleset, ref, cspace, obs, avg);
    nDEi(:,i)=nDEi_;
    nDEavg(i)=nDEavg_;
    Jabt(:,:,i)=Jabt_;
    Jabr(:,:,i)=Jabr_;
    T(i)=T_;
    dc(i)=dc_(1);
    xyzt(:,:,i)=xyzt_;
    xyzr(:,:,i)=xyzr_;

end

if isempty(cfactor) | numel(cfactor)>1
    samplesetF1F12=sampleset;
    if numel(cfactor)>1;%replace F1F12 with set of lamps in cfactor
        F1F12=cfactor;
    end
    for i=1:size(F1F12,2)-1;
        spdiF1F12=[F1F12(:,1),F1F12(:,i+1)];
        [nDEiF1F12(:,i),nDEavgF1F12(i),samplesetF1F12]=cri_engine_(spdiF1F12, samplesetF1F12, ref, cspace, obs, avg);
        [DEiF1F12(:,i),DEavgF1F12(i)]=cri_engine_(spdiF1F12, 14, [], 'U*V*W*', 2, 'mean');
        RaF1F12(i)=100-4.6*DEavgF1F12(i);
    end
%find cfactor that results in CIE Ra (F1-F12) = CRI Ra (F1-F12)
if ~strcmp(scaling,'none');[cfactor]=findcfactor(nDEavgF1F12,DEavgF1F12,scaling,1/50);end
end

%rescale color differences to index value
switch scaling
    case 'nonlin'
            CRIRi= 100 * (2 ./ (exp((cfactor) .* abs(nDEi) .^ (3 / 2)) + 1)) .^ 2;
            CRIRa = 100 * (2 ./ (exp((cfactor) .* abs(nDEavg) .^ (3 / 2)) + 1)) .^ 2;
        
    case 'lin'
        CRIRi=100-cfactor.*abs(nDEi);
        CRIRa = 100-cfactor.*abs(nDEavg);
        
    case 'log'
        CRIRi=10.*(log(exp((100-cfactor.*nDEi)./ 10) + 1));
        CRIRa=10.*(log(exp((100-cfactor.*nDEavg)./ 10) + 1));
    case 'none'
        CRIRi=nDEi;
        CRIRa=nDEavg;
end

end

