00,0.280000000000000,0.535000000000000,0.592000000000000,0.731000000000000,0.836000000000000,0.756000000000000,0.403000000000000,0.702000000000000,0.745000000000000,0.454000000000000;];
        CIETCS=[(360:5:830)',formn(CIETCS,3)];%get to format as specified in CIE13.3
        sampleset=CIETCS(:,1:9);%use only first 8 samples!
        
    otherwise
        if isempty(sampleset)
            error('Empty sampleset, enter 17 (HL17), 14 (CIETCS) or a sampleset')
        end
end

%interpolate rfls first to save time in spd2xyz!
rfl=sampleset;
if size(rfl,1)==size(spd,1);if (sum(abs(rfl(:,1)-spd(:,1))<1e-6)==size(spd,1));interpolaterfls=0;else;interpolaterfls=1;end;else;interpolaterfls=1;end%check if rfl interpolation is necessary
if interpolaterfls==1;
        for i=1:size(rfl,2)-1;
            rfl_(:,i)=interpK(rfl(:,1),rfl(:,i+1),spd(:,1),'linear'); 
        end
    else
        rfl_=rfl(:,2:end);
    end
sampleset=[spd(:,1),rfl_];

%calculate colour temperature
[XYZWT]=spd2xyz(spd,2,0);
[T,dc]=CCTa(XYZWT,2);

%calculate sample XYZ under test light source
[XYZT,XYZWT]=spd2xyz(spd,obs,0,sampleset);

%calculate reference illuminant
if isempty(ref);
    Sr=CCT2CIEref(T,lambda);
else;
    Sr=ref; %use user-defined
    Sr=[interpK(Sr(:,1),Sr(:,2),lambda,'v5cubic')];
    Sr=[lambda,Sr./(sum(Sr).*abs(lambda(1)-lambda(2)))];
    Sr(isnan(Sr(:,2)),2)=0;
end

%calculate sample XYZ under reference illuminant
[XYZR,XYZWR]=spd2xyz(Sr,obs,0,sampleset);


%calculate colour coordinates
switch cspace
    case 'U*V*W*'
        %calculate CIE1960uv
        dp=6;
        utt=4*XYZWT(1)/(XYZWT(1)+15*XYZWT(2)+3*XYZWT(3));utt=formn(utt,dp);
        vtt=6*XYZWT(2)/(XYZWT(1)+15*XYZWT(2)+3*XYZWT(3));vtt=formn(vtt,dp);
        utr=4*XYZWR(1)/(XYZWR(1)+15*XYZWR(2)+3*XYZWR(3));utr=formn(utr,dp);
        vtr=6*XYZWR(2)/(XYZWR(1)+15*XYZWR(2)+3*XYZWR(3));vtr=formn(vtr,dp);
        
        %calculate duv
        duv=sign(vtt-vtr).*sqrt((utt-utr).^2+(vtt-vtr).^2);
        dc=duv;

        %perform von Kries CAT 
        XWR=XYZWR(1);YWR=XYZWR(2);ZWR=XYZWR(3);
        urr=4*XWR/(XWR+15*YWR+3*ZWR);urr=formn(urr,dp);
        vrr=6*YWR/(XWR+15*YWR+3*ZWR);vrr=formn(vrr,dp);

        ukk=4*XYZWT(1)/(XYZWT(1)+15*XYZWT(2)+3*XYZWT(3));ukk=formn(ukk,dp);
        vkk=6*XYZWT(2)/(XYZWT(1)+15*XYZWT(2)+3*XYZWT(3));vkk=formn(vkk,dp);

        crr=(4-urr-10*vrr)/vrr; crr=formn(crr,dp);          % cr
        drr=(1.708*vrr+0.404-1.481*urr)/vrr;  drr=formn(drr,dp);  %dr

        ckk=(4-ukk-10*vkk)/vkk;   ckk=formn(ckk,dp);           %ck
        dkk=(1.708*vkk+0.404-1.481*ukk)/vkk; dkk=formn(dkk,dp);  %dk

        ur=zeros(1,size(sampleset,2)-1);
        vr=zeros(1,size(sampleset,2)-1);
        uk=zeros(1,size(sampleset,2)-1);
        vk=zeros(1,size(sampleset,2)-1);

        XYZR_=[XYZR;XYZWR];
        XYZT_=[XYZT;XYZWT];

        for i=1:size(sampleset,2)-1
            ur(i)=4*XYZR(i,1)/(XYZR(i,1)+15*XYZR(i,2)+3*XYZR(i,3));ur(i)=formn(ur(i),dp);
            vr(i)=6*XYZR(i,2)/(XYZR(i,1)+15*XYZR(i,2)+3*XYZR(i,3));vr(i)=formn(vr(i),dp);
            cr(i)=(4-ur(i)-10*vr(i))/vr(i);cr(i)=formn(cr(i),dp);
            dr(i)=(1.708*vr(i)+0.404-1.481*ur(i))/vr(i);dr(i)=formn(dr(i),dp);
         end

        for i=1:size(sampleset,2)-1
            uk(i)=4*XYZT(i,1)/(XYZT(i,1)+15*XYZT(i,2)+3*XYZT(i,3));uk(i)=formn(uk(i),dp);
            vk(i)=6*XYZT(i,2)/(XYZT(i,1)+15*XYZT(i,2)+3*XYZT(i,3));vk(i)=formn(vk(i),dp);
            ck(i)=(4-uk(i)-10*vk(i))/vk(i);ck(i)=formn(ck(i),dp);
            dk(i)=(1.708*vk(i)+0.404-1.481*uk(i))/vk(i);dk(i)=formn(dk(i),dp);
            u1k(i)=(10.872+0.404*ck(i)*crr/ckk-4*dk(i)*drr/dkk)/(16.518+1.481*ck(i)*crr/ckk-dk(i)*drr/dkk);u1k(i)=formn(u1k(i),dp);  % u'k(i)
            v1k(i)=5.520/(16.518+1.481*ck(i)*crr/ckk-dk(i)*drr/dkk);v1k(i)=formn(v1k(i),dp);  % v'k(i)
         end

        YR=XYZR(:,2);
        YT=XYZT(:,2);
        
        %and calculate U*V*W* 
        for i=1:size(sampleset,2)-1
            Wr(i)=25*YR(i)^(1/3)-17;Wr(i)=formn(Wr(i),dp);
            Ur(i)=13*Wr(i)*(ur(i)-urr);Ur(i)=formn(Ur(i),dp);
            Vr(i)=13*Wr(i)*(vr(i)-vrr);Vr(i)=formn(Vr(i),dp);

            Wk(i)=25*YT(i)^(1/3)-17;Wk(i)=formn(Wk(i),dp);
            Uk(i)=13*Wk(i)*(u1k(i)-urr);Uk(i)=formn(Uk(i),dp);
            Vk(i)=13*Wk(i)*(v1k(i)-vrr);Vk(i)=formn(Vk(i),dp);
        end
        
        Jabr=[Wr',Ur',Vr'];
        Jabt=[Wk',Uk',Vk'];
        
        
    case 'cam02ucs'
        %set CAM02UCS parameters
        Yb=20;F=1;Did=1;Nc=1;c=0.69;LA=100;
        
        %calculate color coordinates of test source
        [J,C,H,M,s,Q,h,Hc,D,A,td,InfSucFail]=CIECAM02ForwardM(XYZT,XYZWT,Yb,Did,F,Nc,c,LA);
        Jc=(1+100*0.007)*J./(1+0.007*J);
        Mc=(1/0.0228)*log(1+0.0228*M);
        aMc=Mc.*cos(h*pi/180);
        bMc=Mc.*sin(h*pi/180);
        Jabt=[Jc',aMc',bMc'];
        
        %calculate color coordinates of reference illuminant
        [J,C,H,M,s,Q,h,Hc,D,A,td,InfSucFail]=CIECAM02ForwardM(XYZR,XYZWR,Yb,Did,F,Nc,c,LA);
        Jr=(1+100*0.007)*J./(1+0.007*J);
        Mr=(1/0.0228)*log(1+0.0228*M);
        aMr=Mr.*cos(h*pi/180);
        bMr=Mr.*sin(h*pi/180);
        Jabr=[Jr',aMr',bMr'];
end

%calculate color differences
DEi=sqrt((Jabr(:,1)-Jabt(:,1)).^2+(Jabr(:,2)-Jabt(:,2)).^2+(Jabr(:,3)-Jabt(:,3)).^2);


%calculate average color difference
switch avg
    case 'rms'
        DEavg=sqrt(sum(DEi.^2)./length(DEi));
    case 'mean'
        DEavg=sum(DEi)./length(DEi);
    case 'median';
        DEavg=median(DEi);
    case 'geomean'
        DEavg=geomean(DEi);
    case 'cumsum'
        bins=linspace(0,ceil(max(DEi)),ceil(max(DEi))+1);
        %bins=linspace(0,20,20+1);
        x=hist(DEi,bins);
        x=x+bins./10000;
        x=x./numel(DEi);
        cumsumx=cumsum(x)./sum(x);
        DEavg_=interp1(cumsumx,bins,0.80,'lagrange');
        figure(112);subplot(1,2,1);plot(bins,x,'k.-')
        figure(112);subplot(1,2,2);plot(cumsumx,bins,'k.-')
        hold on;plot(0.8,DEavg_,'ro');hold off;
        %DEavg_=sum(cumsumx(cumsumx<=0.8))./numel(cumsumx(cumsumx<=0.8));
        DEavg=DEavg_;%return
end

end

