function [cfactor]=findcfactor(nDEavgF1F12,DEavgF1F12,rescaling,cfactor0)
%calculate cfactor using F1-F12

global teller_cfactor
teller_cfactor=0;

%optimize cfactor
%disp('Optimizing cfactor of CRI2012 for sampleset --> mean(nRa12) == mean(CIE Ra12) ...')
opts=optimset('fminsearch');
opts.TolFun=0.005;
cfactor=fminsearch(@(cfactor) optimfcn(cfactor,nDEavgF1F12,DEavgF1F12,rescaling),cfactor0,opts);
% close(102);
end

%--------------------------------------------------------------------------

function [F]=optimfcn(cfactor,nDEavgF1F12,DEavgF1F12,rescaling)
global teller_cfactor
teller_cfactor=teller_cfactor+1;

%calculate average RaF1F12 
RaF1F12=100-4.6.*DEavgF1F12;
RaF1F12_mu=average(RaF1F12,'mean');

%calculate RaF1F12 and its average
switch rescaling
    case 'lin'
        nRaF1F12=(100-cfactor*nDEavgF1F12)';
    case 'nonlin'
        nRaF1F12 = 100 * (2 ./ (exp((cfactor) .* abs(nDEavgF1F12) .^ (3 / 2)) + 1)) .^ 2;
    case 'log'
        nRaF1F12=10.*(log(exp((100-cfactor*nDEavgF1F12)./ 10) + 1));
end
nRaF1F12_mu=average(nRaF1F12,'mean');

%calculate fitness value
F=abs(nRaF1F12_mu-RaF1F12_mu);

%plot intermediate optimization results
% figure(102);subplot(1,2,1);
% hold on;plot(teller_cfactor,RaF1F12_mu,'r.');plot(teller_cfactor,nRaF1F12_mu,'b.')
% subplot(1,2,2);hold on;plot(teller_cfactor,1./cfactor,'b.');
end

%--------------------------------------------------------------------------

function xmu=average(x,avg)
switch avg
    case 'mean'
        xmu=mean(x);
    case 'median'
        xmu=median(x);
    case 'rms'
        xmu=sqrt(sum(x.^2)./numel(x));
        
end
end
